<script setup lang="ts">
import {computed,ref} from 'vue';import {useEditor} from '../stores/editor';import {area,bounds,deriveWalls,bendWall} from '../domain/geometry';
import {uid} from '../domain/project';
const e=useEditor(),target=ref(''),side=ref<'right'|'left'|'top'|'bottom'>('right'),shift=ref(.1),bendX=ref(0),bendZ=ref(0),edge=ref(0);
const room=computed(()=>e.document.rooms.find(r=>r.id===e.selected?.id)),wall=computed(()=>e.walls.find(w=>w.id===e.selected?.id)),opening=computed(()=>e.document.openings.find(o=>o.id===e.selected?.id));
const box=computed(()=>room.value?bounds(room.value.points):null);
function number(event:Event){return Number((event.target as HTMLInputElement).value);}
function resize(axis:'x'|'z',value:number){if(!room.value)return;const id=room.value.id;e.architectural('Размер комнаты',p=>{const r=p.rooms.find(r=>r.id===id)!,b=bounds(r.points);const old=axis==='x'?b.maxX-b.minX:b.maxZ-b.minZ;if(value<.4||value>100)throw new Error('Размер комнаты от 0,4 до 100 м');if(deriveWalls(p).some(w=>w.roomIds.length===2&&w.roomIds.includes(id)))throw new Error('Для соединённых комнат меняйте положение общей стены');const origin=axis==='x'?b.minX:b.minZ;r.points.forEach(v=>{v[axis]=origin+(v[axis]-origin)*value/old;});});}
function addOpening(kind:'door'|'window'){if(!wall.value)return;const id=uid(),w=wall.value;e.architectural('Добавить проём',p=>{p.openings.push({id,wallId:w.id,kind,offset:w.length/2,width:Math.min(kind==='door'?.9:1.4,w.length-.1),height:Math.min(kind==='door'?2.1:1.3,p.height-(kind==='door'?0:.9)),sill:kind==='door'?0:.9});});e.selected={kind:'opening',id};}
function openingField(key:'offset'|'width'|'height'|'sill',value:number){const id=opening.value!.id;e.architectural('Размер проёма',p=>{p.openings.find(o=>o.id===id)![key]=value;});}
</script>
<template>
<section v-if="room&&box" class="inspector-section"><div class="eyebrow">Помещение</div><h2>{{room.name}}</h2><label>Название<input :value="room.name" @change="e.architectural('Название',p=>{p.rooms.find(r=>r.id===room!.id)!.name=($event.target as HTMLInputElement).value})"></label><div class="metric">{{area(room.points).toFixed(2)}} <small>м² внутри стен</small></div>
<label>Ширина, м<input type="number" min="0.4" max="100" step="0.05" :value="(box.maxX-box.minX).toFixed(2)" @change="resize('x',number($event))"><input aria-label="Ширина ползунком" type="range" min="0.5" max="15" step="0.1" :value="box.maxX-box.minX" @change="resize('x',number($event))"></label>
<label>Длина, м<input type="number" min="0.4" max="100" step="0.05" :value="(box.maxZ-box.minZ).toFixed(2)" @change="resize('z',number($event))"><input aria-label="Длина ползунком" type="range" min="0.5" max="15" step="0.1" :value="box.maxZ-box.minZ" @change="resize('z',number($event))"></label>
<h3>Соединить с комнатой</h3><select v-model="target"><option value="">Выберите комнату</option><option v-for="r in e.document.rooms.filter(r=>r.id!==room!.id)" :value="r.id">{{r.name}}</option></select><select v-model="side"><option value="right">Справа</option><option value="left">Слева</option><option value="bottom">Снизу</option><option value="top">Сверху</option></select><button :disabled="!target" @click="e.attach(room!.id,target,side)">Соединить</button>
<button @click="e.architectural('Отсоединить',p=>{const r=p.rooms.find(r=>r.id===room!.id)!,b=bounds(r.points),all=bounds(p.rooms.flatMap(r=>r.points));r.points.forEach(v=>v.x+=all.maxX-b.minX+1)})">Отсоединить</button>
<details><summary>Изменить контур</summary><label>Сегмент<select v-model.number="edge"><option v-for="(_,i) in room.points" :value="i">Стена {{i+1}}</option></select></label><label>Новая точка X<input type="number" step="0.1" v-model.number="bendX"></label><label>Новая точка Z<input type="number" step="0.1" v-model.number="bendZ"></label><button @click="e.architectural('Сгиб стены',p=>bendWall(p,room!.id,edge,bendX,bendZ))">Добавить точку сгиба</button><p class="hint">Координаты в метрах. Прямые и тупые углы; без пересечения контура.</p></details>
<button class="danger" @click="e.removeSelected">Удалить комнату</button></section>
<section v-else-if="wall" class="inspector-section"><div class="eyebrow">{{wall.roomIds.length===2?'Общая стена':'Наружная стена'}}</div><h2>{{wall.length.toFixed(2)}} м</h2><p>Толщина {{(wall.thickness*1000).toFixed(0)}} мм</p><label>Сдвиг стены, м<input type="number" step="0.05" v-model.number="shift"></label><button @click="e.moveWall(wall!.id,shift)">Сдвинуть стену</button><p class="hint">Положительное направление — наружу из первой комнаты.</p><h3>Проёмы</h3><button @click="addOpening('door')">Добавить дверь</button><button @click="addOpening('window')">Добавить окно</button></section>
<section v-else-if="opening" class="inspector-section"><div class="eyebrow">Проём</div><h2>{{opening.kind==='door'?'Дверь':'Окно'}}</h2><label v-for="field in (['offset','width','height','sill'] as const)">{{({offset:'Центр от начала стены',width:'Ширина',height:'Высота',sill:'Высота от пола'})[field]}}<input type="number" step="0.05" :value="opening[field]" @change="openingField(field,number($event))"></label><button class="danger" @click="e.removeSelected">Удалить проём</button></section>
<section v-else class="inspector-section"><div class="eyebrow">Инспектор</div><h2>Выберите объект</h2><p class="hint">Нажмите на комнату или стену на плане, чтобы изменить размеры и добавить проёмы.</p></section>
</template>
